# Adicionando Verificador de Cupom ao Controller

Para adicionar a funcionalidade de verificação de cupom (aplicar um cupom em um pedido/produto), você precisa adicionar uma nova ação no controller. Vou mostrar como fazer isso de forma completa e segura.

## Nova ação: `apply_coupon`

Adicione este método ao seu controller `Coupons`:

```php
public function apply_coupon($id)
{
    // Validação básica do ID
    $id = intval($this->input->post('coupon_id'));

    if ($id === false || !is_numeric($id)) {
        set_alert('danger', 'Cupom inválido. Por favor, selecione um cupom válido.');
        redirect(admin_url('ecommerce/coupons'));
        exit;
    }

    // Busca o cupom pelo código ou ID
    // Supondo que o modelo tenha o método get_coupon($id); caso não tenha, ajuste aqui
    try {
        $coupon = $this->coupons_model->get_coupon($id);
    } catch (Exception $e) {
        set_alert('danger', 'Erro ao buscar cupom: ' . $e->getMessage());
        redirect(admin_url('ecommerce/coupons'));
        exit;
    }

    // Se o cupom não foi encontrado
    if (!$coupon) {
        set_alert('danger', 'Cupom não encontrado!');
        redirect($_SERVER['HTTP_REFERER']);
        exit;
    }

    // --- Validações de negócio -------------------------------------------

    // 1) Cupom expirado?
    $now = date('Y-m-d H:i:s');
    if ($coupon->valid_to && $now > $coupon->valid_to) {
        set_alert('danger', 'Este cupom está expirado (válido até: ' . 
            date('d/m/Y H:i', strtotime($coupon->valid_to)) . ').');
        redirect($_SERVER['HTTP_REFERER']);
        exit;
    }

    // 2) Cupom sem data de validade começando
    if ($coupon->valid_from && $now < $coupon->valid_from) {
        set_alert('danger', 'Este cupom ainda não está válido (válido a partir de: ' . 
            date('d/m/Y H:i', strtotime($coupon->valid_from)) . ').');
        redirect($_SERVER['HTTP_REFERER']);
        exit;
    }

    // 3) Código já em uso por outro cupom ativo
    $existing = $this->coupons_model->get_coupon_by_code($coupon->code);
    if ($existing && $existing->id != $id) {
        // Só bloqueia se o outro cupom estiver ativo (não vencido/expirado)
        $activeNow = null;
        if ($existing->valid_to && date('Y-m-d H:i:s') > $existing->valid_to) {
            $activeNow = false; // expirado, pode reutilizar
        } elseif ($existing->valid_from && date('Y-m-d H:i:s') < $existing->valid_from) {
            $activeNow = false; // futuro, pode ignorar
        } else {
            $activeNow = true; // ativo → bloquear
        }

        if ($activeNow) {
            set_alert('danger', 'O código "' . $coupon->code . '" já está ativo em outro cupom. ' .
                'Escolha um código diferente.');
            redirect($_SERVER['HTTP_REFERER']);
            exit;
        }
    }

    // 4) Restrição para novos usuários (se aplicável)
    $current_user_is_new = (isset($this->session->userdata['is_new']) && 
                            $this->session->userdata['is_new'] == 1);

    if ($coupon->for_new_users && !$current_user_is_new) {
        set_alert('danger', 'Este cupom é exclusivo para novos usuários.');
        redirect($_SERVER['HTTP_REFERER']);
        exit;
    }

    // 5) Cupom não reutilizável (single use)
    if ($coupon->is_reusable == 0) {
        // Aqui você precisaria verificar se o cupom já foi usado anteriormente.
        // Exemplo usando tabela de uso (ex: coupon_usages):
        $already_used = $this->db->where('coupon_id', $id)
                                  ->where('used', 1)
                                  ->countAll();

        if ($already_used > 0) {
            set_alert('danger', 'Este cupom só pode ser usado uma vez e já foi utilizado.');
            redirect($_SERVER['HTTP_REFERER']);
            exit;
        }
    }

    // --- Aplicação do cupom ---------------------------------------------

    // Suponha que você tem um serviço/modelo para aplicar o desconto
    // Exemplo: $this->orders_model->apply_coupon($order_id, $coupon_id);
    // Ou pode ser feito diretamente via model de cupons com retorno do novo valor

    try {
        // Salva o histórico de uso (opcional, mas recomendado)
        $this->db->insert('coupon_usages', [
            'coupon_id' => $id,
            'used_at' => date('Y-m-d H:i:s'),
            'ip_address' => ip_longnum(($_SERVER['REMOTE_ADDR'] ?? '127.0.0.1')),
            // adicione user_id, order_id etc conforme sua estrutura
        ]);

        // Aqui você aplica o desconto onde for necessário
        // Exemplo genérico — ajuste conforme sua arquitetura:
        // $total_before = ...;
        // $discount = $coupon->discount_value * ($coupon->discount_type == 'percent' ? 
        //     (float)$total_before / 100 : 1);
        // $total_after = $total_before - $discount;

        // Para demonstração, apenas retornamos os dados do cupom aplicado:
        $applied_data = [
            'message' => 'Cupom "' . $coupon->code . '" aplicado com sucesso!',
            'discount_type' => $coupon->discount_type,
            'discount_value' => $coupon->discount_value,
            'valid_from' => $coupon->valid_from ? date('d/m/Y H:i', strtotime($coupon->valid_from)) : '',
            'valid_to'   => $coupon->valid_to ? date('d/m/Y H:i', strtotime($coupon->valid_to)) : '',
        ];

        // Carrega a view de aplicação do cupom passando os dados
        $this->load->view('ecommerce/apply_coupon', array_merge($applied_data, $coupon));

    } catch (Exception $e) {
        set_alert('danger', 'Falha ao aplicar o cupom: ' . $e->getMessage());
        redirect($_SERVER['HTTP_REFERER']);
        exit;
    }
}
```

